package com.game_manager.gm.workflow;
import com.game_manager.gm.audit.*; import com.game_manager.gm.common.error.ApplicationException; import com.game_manager.gm.common.security.*; import com.game_manager.gm.document.DocumentService; import com.game_manager.gm.notification.*; import com.game_manager.gm.user.*; import com.game_manager.gm.workflow.dto.*; import io.micrometer.core.instrument.MeterRegistry; import java.time.*; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import tools.jackson.databind.ObjectMapper;
@Service public class WorkflowService {private static final Set<String>TERMINALS=Set.of("APPROVED","REJECTED","CANCELLED");private final WorkflowDefinitionRepository definitions;private final WorkflowDefinitionVersionRepository versions;private final WorkflowInstanceRepository instances;private final WorkflowStepRepository steps;private final WorkflowDecisionRepository decisions;private final WorkflowCommentRepository comments;private final WorkflowDocumentLinkRepository links;private final WorkflowDefinitionValidator validator;private final CurrentUserProvider current;private final UserRepository users;private final DocumentService documents;private final WorkflowNotificationGateway notifications;private final AuditWriter audit;private final ObjectMapper mapper;private final Clock clock;private final MeterRegistry metrics;
 public WorkflowService(WorkflowDefinitionRepository d,WorkflowDefinitionVersionRepository v,WorkflowInstanceRepository i,WorkflowStepRepository s,WorkflowDecisionRepository x,WorkflowCommentRepository c,WorkflowDocumentLinkRepository l,WorkflowDefinitionValidator validator,CurrentUserProvider current,UserRepository users,DocumentService documents,WorkflowNotificationGateway notifications,AuditWriter audit,ObjectMapper mapper,Clock clock,MeterRegistry metrics){definitions=d;versions=v;instances=i;steps=s;decisions=x;comments=c;links=l;this.validator=validator;this.current=current;this.users=users;this.documents=documents;this.notifications=notifications;this.audit=audit;this.mapper=mapper;this.clock=clock;this.metrics=metrics;}
 @Transactional(readOnly=true)public List<WorkflowDefinitionResponse> definitions(){AuthenticatedUser actor=current.requireCurrentUser();requireAny(actor,Permission.WORKFLOW_SUBMIT,Permission.WORKFLOW_MANAGE);return definitions.findAllByOrderByName().stream().filter(d->d.isEnabled()||RolePermissions.has(actor.role(),Permission.WORKFLOW_MANAGE)).map(d->WorkflowDefinitionResponse.from(d,versions.findByDefinitionIdAndVersionNumber(d.getId(),d.getActiveVersion()).orElseThrow())).toList();}
 @Transactional public WorkflowDefinitionResponse publish(WorkflowDefinitionRequest input){AuthenticatedUser actor=require(Permission.WORKFLOW_MANAGE);validator.validate(input);WorkflowDefinition definition=definitions.findByDefinitionKeyAndEnabledTrue(input.key()).orElseGet(()->{WorkflowDefinition d=new WorkflowDefinition();d.setDefinitionKey(input.key());d.setActiveVersion(0);return d;});definition.setName(input.name().trim());definition.setEnabled(input.enabled());int number=definition.getActiveVersion()+1;definition.setActiveVersion(number);definitions.saveAndFlush(definition);WorkflowDefinitionVersion value=new WorkflowDefinitionVersion();value.setDefinition(definition);value.setVersionNumber(number);value.setSchemaJson(mapper.writeValueAsString(toSchema(input)));value.setPublishedBy(actor.id());value.setPublishedAt(clock.instant());versions.saveAndFlush(value);audit.write("WORKFLOW_DEFINITION_PUBLISHED","WORKFLOW_DEFINITION",definition.getId(),null,Map.of("version",number),null,AuditVisibility.ADMIN_ONLY);return WorkflowDefinitionResponse.from(definition,value);}
 @Transactional public WorkflowSummaryResponse create(CreateWorkflowRequest input){AuthenticatedUser actor=require(Permission.WORKFLOW_SUBMIT);WorkflowDefinition definition=definitions.findByDefinitionKeyAndEnabledTrue(input.definitionKey()).orElseThrow(this::notFound);WorkflowDefinitionVersion version=versions.findByDefinitionIdAndVersionNumber(definition.getId(),definition.getActiveVersion()).orElseThrow();WorkflowSchema schema=schema(version);WorkflowInstance instance=new WorkflowInstance();instance.setDefinitionVersion(version);instance.setRequesterId(actor.id());instance.setTitle(input.title().trim());instance.setAmount(input.amount());instance.setDescription(input.description().trim());instance.setStatus(WorkflowStatus.ACTIVE);instances.saveAndFlush(instance);activate(instance,schema,schema.initialStep());audit.write("WORKFLOW_STARTED","WORKFLOW",instance.getId(),null,Map.of("definition",definition.getDefinitionKey()),null,AuditVisibility.OWNER_ONLY);metrics.counter("gmanager.workflow.started","definition",definition.getDefinitionKey()).increment();return WorkflowSummaryResponse.from(instance,allowed(instance,actor));}
 @Transactional(readOnly=true)public List<WorkflowSummaryResponse> inbox(){AuthenticatedUser actor=require(Permission.WORKFLOW_ACT);return steps.inbox(actor.id(),actor.role().name()).stream().map(s->WorkflowSummaryResponse.from(s.getInstance(),allowed(s.getInstance(),actor))).toList();}
 @Transactional(readOnly=true)public List<WorkflowSummaryResponse> mine(){AuthenticatedUser actor=current.requireCurrentUser();return instances.findByRequesterIdOrderByCreatedAtDesc(actor.id()).stream().map(i->WorkflowSummaryResponse.from(i,allowed(i,actor))).toList();}
 @Transactional(readOnly=true)public WorkflowDetailResponse detail(UUID id){AuthenticatedUser actor=current.requireCurrentUser();WorkflowInstance instance=instances.detail(id).orElseThrow(this::notFound);requireVisible(instance,actor);return detail(instance,actor);}
 @Transactional public WorkflowDetailResponse act(UUID id,WorkflowActionRequest input){AuthenticatedUser actor=current.requireCurrentUser();WorkflowInstance instance=instances.locked(id).orElseThrow(this::notFound);if(!Objects.equals(instance.getVersion(),input.version()))throw new ApplicationException(HttpStatus.CONFLICT,"Workflow changed; refresh and retry");if(instance.getStatus()!=WorkflowStatus.ACTIVE)throw new ApplicationException(HttpStatus.CONFLICT,"Workflow is already completed");WorkflowStep step=steps.findByInstanceIdAndStatus(id,StepStatus.ACTIVE).orElseThrow();requireAssigned(step,instance,actor);WorkflowSchema schema=schema(instance.getDefinitionVersion());String action=input.action().toUpperCase(Locale.ROOT);WorkflowSchema.Transition transition=schema.transition(step.getStepKey(),action);if(transition==null)throw new ApplicationException(HttpStatus.CONFLICT,"Workflow transition is not allowed");if(transition.reasonRequired()&&(input.reason()==null||input.reason().isBlank()))throw new ApplicationException(HttpStatus.BAD_REQUEST,"Reason is required for this action");Instant now=clock.instant();step.setStatus(StepStatus.COMPLETED);step.setCompletedAt(now);WorkflowDecision decision=new WorkflowDecision();decision.setInstance(instance);decision.setStep(step);decision.setActorId(actor.id());decision.setAction(action);decision.setReason(normalize(input.reason()));decision.setFromStepKey(step.getStepKey());decision.setToStepKey(transition.target());decision.setDecidedAt(now);decisions.saveAndFlush(decision);if(TERMINALS.contains(transition.target())){instance.setStatus(WorkflowStatus.valueOf(transition.target()));instance.setCurrentStepKey(null);instance.setDueAt(null);instance.setCompletedAt(now);notifications.send(decision.getId(),instance.getRequesterId(),NotificationType.WORKFLOW_COMPLETED,"Workflow je završen",instance.getTitle()+": "+transition.target());metrics.counter("gmanager.workflow.completed","outcome",transition.target().toLowerCase()).increment();}else activate(instance,schema,transition.target());audit.write("WORKFLOW_DECISION","WORKFLOW",id,Map.of("step",step.getStepKey()),Map.of("action",action,"target",transition.target()),normalize(input.reason()),AuditVisibility.OWNER_ONLY);return detail(instance,actor);}
 @Transactional public WorkflowDetailResponse comment(UUID id,WorkflowCommentRequest input){AuthenticatedUser actor=current.requireCurrentUser();WorkflowInstance instance=instances.detail(id).orElseThrow(this::notFound);requireVisible(instance,actor);WorkflowComment value=new WorkflowComment();value.setInstance(instance);value.setAuthorId(actor.id());value.setBody(input.body().trim());comments.saveAndFlush(value);audit.write("WORKFLOW_COMMENTED","WORKFLOW",id,null,Map.of("commentAdded",true),null,AuditVisibility.OWNER_ONLY);return detail(instance,actor);}
 @Transactional public WorkflowDetailResponse link(UUID id,WorkflowLinkRequest input){AuthenticatedUser actor=current.requireCurrentUser();WorkflowInstance instance=instances.detail(id).orElseThrow(this::notFound);requireVisible(instance,actor);boolean exists=documents.list("WORKFLOW_ATTACHMENT",id).stream().anyMatch(d->d.id().equals(input.documentId()));if(!exists)throw new ApplicationException(HttpStatus.NOT_FOUND,"Document not found");if(!links.existsByInstanceIdAndDocumentId(id,input.documentId())){WorkflowDocumentLink link=new WorkflowDocumentLink();link.setInstance(instance);link.setDocumentId(input.documentId());link.setLinkedBy(actor.id());links.saveAndFlush(link);}return detail(instance,actor);}
 private void activate(WorkflowInstance instance,WorkflowSchema schema,String key){WorkflowSchema.Step definition=schema.step(key);Instant now=clock.instant();WorkflowStep step=new WorkflowStep();step.setInstance(instance);step.setStepKey(key);step.setAssigneeRole(definition.role());step.setAssigneeId(definition.role().equals("SUBMITTER")?instance.getRequesterId():null);step.setStatus(StepStatus.ACTIVE);step.setStartedAt(now);step.setDueAt(now.plus(Duration.ofHours(definition.dueHours())));step.setReminderAt(now.plus(Duration.ofHours(definition.reminderHours())));steps.saveAndFlush(step);instance.setCurrentStepKey(key);instance.setDueAt(step.getDueAt());recipients(step).forEach(id->notifications.send(step.getId(),id,NotificationType.WORKFLOW_ACTION_REQUIRED,"Nova workflow akcija",instance.getTitle()));}
 List<UUID> recipients(WorkflowStep step){if(step.getAssigneeId()!=null)return List.of(step.getAssigneeId());Role role=Role.valueOf(step.getAssigneeRole());return users.findByRoleAndActiveTrueAndDeletedAtIsNull(role).stream().map(User::getId).toList();}
 boolean visible(WorkflowInstance i,AuthenticatedUser a){if(i.getRequesterId().equals(a.id())||RolePermissions.has(a.role(),Permission.WORKFLOW_MANAGE))return true;return steps.findByInstanceIdAndStatus(i.getId(),StepStatus.ACTIVE).map(s->assigned(s,i,a)).orElse(false);}
 private void requireVisible(WorkflowInstance i,AuthenticatedUser a){if(!visible(i,a))throw notFound();}private boolean assigned(WorkflowStep s,WorkflowInstance i,AuthenticatedUser a){return s.getAssigneeId()!=null?s.getAssigneeId().equals(a.id()):s.getAssigneeRole().equals(a.role().name());}private void requireAssigned(WorkflowStep s,WorkflowInstance i,AuthenticatedUser a){if(!assigned(s,i,a)||!RolePermissions.has(a.role(),Permission.WORKFLOW_ACT)&&!i.getRequesterId().equals(a.id()))throw new ApplicationException(HttpStatus.NOT_FOUND,"Workflow not found");}
 List<String> allowed(WorkflowInstance i,AuthenticatedUser actor){if(i.getStatus()!=WorkflowStatus.ACTIVE)return List.of();return steps.findByInstanceIdAndStatus(i.getId(),StepStatus.ACTIVE).filter(s->assigned(s,i,actor)).map(s->{WorkflowSchema sc=schema(i.getDefinitionVersion());return sc.transitions().stream().filter(t->t.from().equals(s.getStepKey())).map(WorkflowSchema.Transition::action).toList();}).orElse(List.of());}
 WorkflowSchema schema(WorkflowDefinitionVersion v){return mapper.readValue(v.getSchemaJson(),WorkflowSchema.class);}private WorkflowSchema toSchema(WorkflowDefinitionRequest r){return new WorkflowSchema(r.initialStep(),r.steps().stream().map(s->new WorkflowSchema.Step(s.key(),s.label(),s.role(),s.dueHours(),s.reminderHours(),s.escalationRole())).toList(),r.transitions().stream().map(t->new WorkflowSchema.Transition(t.from(),t.action(),t.target(),t.reasonRequired())).toList());}
 private WorkflowDetailResponse detail(WorkflowInstance i,AuthenticatedUser a){return new WorkflowDetailResponse(WorkflowSummaryResponse.from(i,allowed(i,a)),i.getDescription(),i.getRequesterId(),steps.findByInstanceIdOrderByStartedAt(i.getId()).stream().map(s->new WorkflowDetailResponse.Step(s.getId(),s.getStepKey(),s.getAssigneeRole(),s.getStatus().name(),s.getStartedAt(),s.getDueAt(),s.getCompletedAt())).toList(),decisions.findByInstanceIdOrderByDecidedAt(i.getId()).stream().map(d->new WorkflowDetailResponse.Decision(d.getId(),d.getActorId(),d.getAction(),d.getReason(),d.getFromStepKey(),d.getToStepKey(),d.getDecidedAt())).toList(),comments.findByInstanceIdOrderByCreatedAt(i.getId()).stream().map(c->new WorkflowDetailResponse.Comment(c.getId(),c.getAuthorId(),c.getBody(),c.getCreatedAt())).toList(),links.findByInstanceId(i.getId()).stream().map(WorkflowDocumentLink::getDocumentId).toList());}
 private AuthenticatedUser require(Permission p){AuthenticatedUser a=current.requireCurrentUser();if(!RolePermissions.has(a.role(),p))throw new ApplicationException(HttpStatus.FORBIDDEN,"Workflow permission required");return a;}private void requireAny(AuthenticatedUser a,Permission...p){if(Arrays.stream(p).noneMatch(x->RolePermissions.has(a.role(),x)))throw new ApplicationException(HttpStatus.FORBIDDEN,"Workflow permission required");}private static String normalize(String s){return s==null||s.isBlank()?null:s.trim();}private ApplicationException notFound(){return new ApplicationException(HttpStatus.NOT_FOUND,"Workflow not found");}
}
